select pallet_info.*
,ware_info.name as ware_name
from  pallet_info  pallet_info

left join ware_info ware_info on pallet_info.ware_code = ware_info.code

     and pallet_info.code = #{code}
     and pallet_info.rfid_code = #{rfidCode}
     and pallet_info.name like concat('%', #{name}, '%')
     and pallet_info.cell_code = #{cellCode}
     and pallet_info.type_code = #{typeCode}
     and pallet_info.type_name like concat('%', #{typeName}, '%')
     and pallet_info.is_empty = #{isEmpty}
     and pallet_info.state = #{state}
     and pallet_info.parent_code = #{parentCode}

mapper.update:
update pallet_info
code = #{code}, name = #{name}, cell_code = #{cellCode}, type_code = #{typeCode}, type_name = #{typeName}, is_empty = #{isEmpty}, parent_code = #{parentCode},
where id = #{id}
